/*
 * RGFS context Data QREG 1
 */
struct rgfs_context_data_qreg1 {
	u32 cid
	    /* CID for replacement in CM header. Used for steering to TX queue. Only one copy can use CID. In TGFS used to change event ID   Select TGFS flow in PSTORM */
	    ;
	u16 bitfields0;
#define RGFS_CONTEXT_DATA_QREG1_CONNECTION_TYPE_MASK          0xF	/* Connection Type for replacement in the CM header (Unused) */
#define RGFS_CONTEXT_DATA_QREG1_CONNECTION_TYPE_SHIFT         0
#define RGFS_CONTEXT_DATA_QREG1_CORE_AFFINITY_MASK            0x3	/* Core Affinity for replacement in the CM header (Unused) */
#define RGFS_CONTEXT_DATA_QREG1_CORE_AFFINITY_SHIFT           4
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_DST_IP_ADDRESS_MASK    0x1	/* Change dst IP address that RSS header refers to. Set 1 to replace inner IPV4 address */
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_DST_IP_ADDRESS_SHIFT   6
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_SRC_IP_ADDRESS_MASK    0x1	/* Change src IP address that RSS header refers to. Set 1 to replace inner IPV4 address */
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_SRC_IP_ADDRESS_SHIFT   7
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_DST_PORT_MASK          0x1	/* Change dst port that RSS header refers to. Set 1 to replace inner UDP/TCP port */
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_DST_PORT_SHIFT         8
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_SRC_PORT_MASK          0x1	/* Change src port that RSS header refers to. Set 1 to replace inner UDP/TCP port */
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_SRC_PORT_SHIFT         9
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_RSS_IPVER_TYPE_MASK    0x1	/* Change IpVerType field in the RSS header. Set 0 */
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_RSS_IPVER_TYPE_SHIFT   10
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_RSS_L4_TYPE_MASK       0x1	/* Change L4Type field in the RSS header. Set 0 */
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_RSS_L4_TYPE_SHIFT      11
#define RGFS_CONTEXT_DATA_QREG1_RSS_L4_TYPE_MASK              0x3	/* Unused */
#define RGFS_CONTEXT_DATA_QREG1_RSS_L4_TYPE_SHIFT             12
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_RSS_OVER_IP_PROT_MASK  0x1	/* Change OVER_IP_PROTOCOL field in the RSS header. Set 0 */
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_RSS_OVER_IP_PROT_SHIFT 14
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_RSS_IPV4_FRAG_MASK     0x1	/* Change Ipv4Frag field in the RSS header. Set 0 */
#define RGFS_CONTEXT_DATA_QREG1_CHANGE_RSS_IPV4_FRAG_SHIFT    15
	u16 dst_port /* Dst port value for replacement. L4 port */ ;
	u16 src_port /* Src port value for replacement. L4 port */ ;
	u16 bitfields1;
#define RGFS_CONTEXT_DATA_QREG1_RSS_IPVER_TYPE_MASK           0x3	/* Unused */
#define RGFS_CONTEXT_DATA_QREG1_RSS_IPVER_TYPE_SHIFT          0
#define RGFS_CONTEXT_DATA_QREG1_RSS_IPV4_FRAG_MASK            0x1	/* Unused */
#define RGFS_CONTEXT_DATA_QREG1_RSS_IPV4_FRAG_SHIFT           2
#define RGFS_CONTEXT_DATA_QREG1_RSS_OVER_IP_PROT_MASK         0xFF	/* Unused */
#define RGFS_CONTEXT_DATA_QREG1_RSS_OVER_IP_PROT_SHIFT        3
#define RGFS_CONTEXT_DATA_QREG1_RESERVED_MASK                 0x1F
#define RGFS_CONTEXT_DATA_QREG1_RESERVED_SHIFT                11
	u32 flow_id
	    /* Flow Id. Used for TMLD aggregation. Always set. Replace last register in TM message. */
	    ;
};

/*
 * RGFS context Data QREG 2
 */
struct rgfs_context_data_qreg2 {
	u32 src_ip
	    /* HDR Modify   IPv4 source IP or IPv6 indirection index. 0 are invalid index. */
	    ;
	u16 bitfields0;
#define RGFS_CONTEXT_DATA_QREG2_FW_POP_TYPE_MASK \
	0x7
#define RGFS_CONTEXT_DATA_QREG2_FW_POP_TYPE_SHIFT \
	0
#define RGFS_CONTEXT_DATA_QREG2_FW_TID0_VALID_MASK \
	0x1			/* TID 0 Valid */
#define RGFS_CONTEXT_DATA_QREG2_FW_TID0_VALID_SHIFT \
	3
#define RGFS_CONTEXT_DATA_QREG2_FW_TID1_VALID_MASK \
	0x1			/* TID 1 Valid */
#define RGFS_CONTEXT_DATA_QREG2_FW_TID1_VALID_SHIFT \
	4
#define RGFS_CONTEXT_DATA_QREG2_FW_FIRST_HDR_VLAN_MODE_MASK \
	0x3			/* POP or PUSH CVLAN out of band (use enum gfs_vlan_mode) */
#define RGFS_CONTEXT_DATA_QREG2_FW_FIRST_HDR_VLAN_MODE_SHIFT \
	5
#define											  \
	RGFS_CONTEXT_DATA_QREG2_RESERVED_DRV_HINT_TBD_WAS_FW_INNER_IPV4_ID_IND_INDEX_MASK \
	0x1FF			/* Drv Hint (TBD). Was: Inner IPV4 ID indirection index. 0 are invalid index. */
#define											   \
	RGFS_CONTEXT_DATA_QREG2_RESERVED_DRV_HINT_TBD_WAS_FW_INNER_IPV4_ID_IND_INDEX_SHIFT \
	7
	u16 fw_command1_sample_len
	    /* 2nd Command sample length (1st command is command0) */ ;
	u32 fw_tid0 /* Counter 0 TID */ ;
	u32 fw_tid1 /* Counter 1 TID */ ;
};

/*
 * RGFS context Data QREG 3
 */
struct rgfs_context_data_qreg3 {
	u32 dst_ip
	    /* HDR Modify   inner IPv4 destination IP or IPv6 indirection index. 0 are invalid index. */
	    ;
	u16 fw_first_hdr_vlan_val /* Tunnel VLAN value */ ;
	u16 bitfields0;
#define RGFS_CONTEXT_DATA_QREG3_XXLOCK_CMD_MASK                     0x7	/* CM HDR override - Clear for drop. No special allocation needed for drop fields. */
#define RGFS_CONTEXT_DATA_QREG3_XXLOCK_CMD_SHIFT                    0
#define RGFS_CONTEXT_DATA_QREG3_FW_MODIFY_INNER_4TUPLE_MASK         0x1	/* Modify 4 tuple  */
#define RGFS_CONTEXT_DATA_QREG3_FW_MODIFY_INNER_4TUPLE_SHIFT        3
#define RGFS_CONTEXT_DATA_QREG3_FW_MODIFY_INNER_MAC_MASK            0x1	/* Modify inner/single ETH header */
#define RGFS_CONTEXT_DATA_QREG3_FW_MODIFY_INNER_MAC_SHIFT           4
#define RGFS_CONTEXT_DATA_QREG3_FW_MODIFY_INNER_IP_DSCP_MASK        0x1	/* Modify inner IP DSCP */
#define RGFS_CONTEXT_DATA_QREG3_FW_MODIFY_INNER_IP_DSCP_SHIFT       5
#define RGFS_CONTEXT_DATA_QREG3_FW_SET_INNER_IP_TTL_HOP_LIMIT_MASK  0x1	/* Modify inner IP TTL or Hop Limit */
#define RGFS_CONTEXT_DATA_QREG3_FW_SET_INNER_IP_TTL_HOP_LIMIT_SHIFT 6
#define RGFS_CONTEXT_DATA_QREG3_FW_DEC_INNER_IP_TTL_HOP_LIMIT_MASK  0x1	/* Decrement inner IP TTL or Hop Limit */
#define RGFS_CONTEXT_DATA_QREG3_FW_DEC_INNER_IP_TTL_HOP_LIMIT_SHIFT 7
#define RGFS_CONTEXT_DATA_QREG3_FW_INNER_VLAN_MODIFY_FLG_MASK       0x3	/* NOP, change VID, change PRI, change whole tag */
#define RGFS_CONTEXT_DATA_QREG3_FW_INNER_VLAN_MODIFY_FLG_SHIFT      8
#define RGFS_CONTEXT_DATA_QREG3_LOAD_ST_CTX_FLG_MASK                0x1	/* CM HDR override - Clear for drop. No special allocation needed for drop fields. */
#define RGFS_CONTEXT_DATA_QREG3_LOAD_ST_CTX_FLG_SHIFT               10
#define RGFS_CONTEXT_DATA_QREG3_FW_TUNNEL_VLAN_MODIFY_FLG_MASK      0x7	/* NOP, POP, PUSH, change VID, change PRI, change whole tag */
#define RGFS_CONTEXT_DATA_QREG3_FW_TUNNEL_VLAN_MODIFY_FLG_SHIFT     11
#define RGFS_CONTEXT_DATA_QREG3_RESERVED_MASK                       0x3
#define RGFS_CONTEXT_DATA_QREG3_RESERVED_SHIFT                      14
	u16 fw_command2_sample_len
	    /* 3rd Command sample length (1st command is command0) */ ;
	u16 fw_inner_vlan_val /* Inner VLAN value */ ;
	u32 bitfields1;
#define RGFS_CONTEXT_DATA_QREG3_FW_INNER_IP_DSCP_MASK               0x3F	/* inner IP DSCP Set value */
#define RGFS_CONTEXT_DATA_QREG3_FW_INNER_IP_DSCP_SHIFT              0
#define RGFS_CONTEXT_DATA_QREG3_FW_INNER_SRC_MAC_IND_INDEX_MASK     0x1FF	/* Inner source      MAC indirection index. 0 are invalid index. */
#define RGFS_CONTEXT_DATA_QREG3_FW_INNER_SRC_MAC_IND_INDEX_SHIFT    6
#define RGFS_CONTEXT_DATA_QREG3_FW_INNER_DEST_MAC_IND_INDEX_MASK    0x1FF	/* Inner destination MAC indirection index. 0 are invalid index. */
#define RGFS_CONTEXT_DATA_QREG3_FW_INNER_DEST_MAC_IND_INDEX_SHIFT   15
#define RGFS_CONTEXT_DATA_QREG3_FW_INNER_IP_TTL_HOP_LIMIT_MASK      0xFF	/* inner IP TTL or Hop Limit Set value */
#define RGFS_CONTEXT_DATA_QREG3_FW_INNER_IP_TTL_HOP_LIMIT_SHIFT     24
};

/*
 * RGFS context Data QREG 4
 */
struct rgfs_context_data_qreg4 {
	u32 fw_tunn_src_ip
	    /* HDR Modify   tunnel IPv4 source IP or IPv6 indirection index. Used by FW. */
	    ;
	u32 flow_mark
	    /* Filter marker. Always set. Replace per-pf config in basic block. Reported by CQE  */
	    ;
	u32 fw_tunn_dest_ip
	    /* HDR Modify   tunnel IPv4 destination IP or IPv6 indirection index. Used by FW. */
	    ;
	u8 fw_tunn_ip_ttl_hop_limit /* Tunnel IP TTL or Hop Limit Set value */ ;
	u8 reserved[3];
};

/*
 * RGFS context Data QREG 5
 */
struct rgfs_context_data_qreg5 {
	union gfs_tunnel_header_flags tunnel_ip_header_flags
	    /* Tunnel IP tunnel header flag union. */ ;
	u16 bitfields0;
#define RGFS_CONTEXT_DATA_QREG5_FW_TUNNEL_SRC_MAC_IND_INDEX_MASK   0x1FF	/* Tunnel source MAC indirection index. 0 are invalid index. */
#define RGFS_CONTEXT_DATA_QREG5_FW_TUNNEL_SRC_MAC_IND_INDEX_SHIFT  0
#define RGFS_CONTEXT_DATA_QREG5_FW_PUSH_TYPE_MASK                  0xF	/* Push headers type. */
#define RGFS_CONTEXT_DATA_QREG5_FW_PUSH_TYPE_SHIFT                 9
#define RGFS_CONTEXT_DATA_QREG5_CID_OVERWRITE_MASK                 0x1	/* RSS HDR override - for CID steering. Disable CID override. */
#define RGFS_CONTEXT_DATA_QREG5_CID_OVERWRITE_SHIFT                13
#define RGFS_CONTEXT_DATA_QREG5_FW_TUNNEL_IP_ECN_MASK              0x3	/* Tunnel IP header flags for PUSH flow: 2 LSBits of tos field. */
#define RGFS_CONTEXT_DATA_QREG5_FW_TUNNEL_IP_ECN_SHIFT             14
	union gfs_tunnel_header_data tunnel_header_data
	    /* VXLAN/GRE tunnel header union. */ ;
	u16 bitfields1;
#define RGFS_CONTEXT_DATA_QREG5_RESERVED2_MASK                     0x7F	/* Modify tunnel source IP address. */
#define RGFS_CONTEXT_DATA_QREG5_RESERVED2_SHIFT                    0
#define RGFS_CONTEXT_DATA_QREG5_FW_TUNNEL_DEST_MAC_IND_INDEX_MASK  0x1FF	/* Tunnel destination MAC indirection index. 0 are invalid index. */
#define RGFS_CONTEXT_DATA_QREG5_FW_TUNNEL_DEST_MAC_IND_INDEX_SHIFT 7
	u32 bitfields2;
#define RGFS_CONTEXT_DATA_QREG5_KEY_ADDR_LDR_HEADER_REGION_MASK    0xFFF	/* RSS HDR override - for queue/CID steering. Only one copy can use queue ID. Limited by 256. Bits 9-11 can be used by context.   */
#define RGFS_CONTEXT_DATA_QREG5_KEY_ADDR_LDR_HEADER_REGION_SHIFT   0
#define RGFS_CONTEXT_DATA_QREG5_CALC_RSS_AND_IND_TBL_MASK          0xF	/* RSS HDR override - For steering. Only one copy can use queue ID. Limited by 1. Bits 1-3 can be used by context. * Cannot Move *  */
#define RGFS_CONTEXT_DATA_QREG5_CALC_RSS_AND_IND_TBL_SHIFT         12
#define RGFS_CONTEXT_DATA_QREG5_FW_TUNNEL_IP_DSCP_MASK             0x3F	/* Tunnel IP DSCP Set value */
#define RGFS_CONTEXT_DATA_QREG5_FW_TUNNEL_IP_DSCP_SHIFT            16
#define RGFS_CONTEXT_DATA_QREG5_DEFAULT_QUEUE_ID_MASK              0x3FF	/* RSS HDR override - For steering. Only one copy can use queue ID. Limited by 511. Bits 9 can be used by context. * Cannot Move *  */
#define RGFS_CONTEXT_DATA_QREG5_DEFAULT_QUEUE_ID_SHIFT             22
};

/*
 * TGFS context Data QREG 1
 */
