#define TGFS_CONTEXT_DATA_QREG1_FW_FIRST_HDR_VLAN_MODE_SHIFT 0
#define TGFS_CONTEXT_DATA_QREG1_FW_TID0_VALID_MASK           0x1	/* TID 0 Valid */
