#define TGFS_CONTEXT_DATA_QREG3_FW_FIRST_HDR_DEST_MAC_IND_INDEX_SHIFT 0
#define TGFS_CONTEXT_DATA_QREG3_FW_FIRST_HDR_SRC_MAC_IND_INDEX_MASK   0x1FF	/* First ETH header source MAC indirection index. 0 for unchanged. Replace basic block register 8 */
#define TGFS_CONTEXT_DATA_QREG3_FW_FIRST_HDR_SRC_MAC_IND_INDEX_SHIFT  9
