#define TGFS_CONTEXT_DATA_QREG3_FW_POP_TYPE_SHIFT                     18
#define TGFS_CONTEXT_DATA_QREG3_FW_INNER_HDR_VLAN_MODE_MASK           0x7	/* Inner ETH header VLAN modification: NOP, POP, PUSH, change VID, change PRI, change whole tag. Replace basic block register 8 (use enum gfs_vlan_mode) */
#define TGFS_CONTEXT_DATA_QREG3_FW_INNER_HDR_VLAN_MODE_SHIFT          21
#define TGFS_CONTEXT_DATA_QREG3_FW_INNER_IP_TTL_HOP_LIMIT_MASK        0xFF	/* inner IP TTL or Hop Limit Set value. Replace basic block register 8. */
#define TGFS_CONTEXT_DATA_QREG3_FW_INNER_IP_TTL_HOP_LIMIT_SHIFT       24
	u16 bitfields1;
#define TGFS_CONTEXT_DATA_QREG3_FW_PUSH_TYPE_MASK                     0xF	/* Push headers type. */
#define TGFS_CONTEXT_DATA_QREG3_FW_PUSH_TYPE_SHIFT                    0
#define TGFS_CONTEXT_DATA_QREG3_FW_INNER_IP_DSCP_MASK                 0x3F	/* inner IP DSCP Set value */
#define TGFS_CONTEXT_DATA_QREG3_FW_INNER_IP_DSCP_SHIFT                4
#define TGFS_CONTEXT_DATA_QREG3_RESERVED0_MASK                        0x3F
#define TGFS_CONTEXT_DATA_QREG3_RESERVED0_SHIFT                       10
	u16 fw_inner_vlan_val /* Inner VLAN value */ ;
	u32 flow_mark /* Filter marker. Pass to Rx if destination is RX_VPORT */
	    ;
