#define TGFS_CONTEXT_DATA_QREG5_FW_TUNNEL_IP_ECN_SHIFT     0
#define TGFS_CONTEXT_DATA_QREG5_FW_TUNNEL_IP_DSCP_MASK     0x3F	/* Tunnel IP DSCP Set value */
