#define TGFS_CONTEXT_DATA_QREG5_FW_ORIGINAL_COPY_FLG_SHIFT 0
#define TGFS_CONTEXT_DATA_QREG5_RSERVED0_MASK              0x7F	/* Original flag set for some copy. */
#define TGFS_CONTEXT_DATA_QREG5_RSERVED0_SHIFT             1
	union gfs_tunnel_header_data tunnel_header_data
	    /* VXLAN/GRE tunnel header union. */ ;
