	    /* This field should be assigned to Virtual Function ID if vf_valid == 1. Otherwise its dont care */
	    ;
	u8 vf_valid;
	u8 relaxed_ordering /* 1 for using relaxed ordering PCI writes */ ;
	__le16 first_reg_srq_id
	    /* The SRQ ID of thr first regular (non XRC) SRQ */ ;
	__le32 reg_srq_base_addr
	    /* Logical base address of first regular (non XRC) SRQ */ ;
