#define ROCE_CREATE_QP_REQ_RAMROD_DATA_RNR_NAK_CNT_SHIFT         12
	u8 max_ord;
	u8 traffic_class /* In case of RRoCE on IPv4 will be used as TOS */ ;
	u8 hop_limit /* In case of RRoCE on IPv4 will be used as TTL */ ;
	u8 orq_num_pages;
	__le16 p_key;
