/*
 * Fast path part of the fcoe storm context of Mstorm
 */
struct fcoe_mstorm_fcoe_conn_st_ctx_fp {
	__le16 xfer_prod /* XferQ producer */ ;
	u8 num_cqs /* Number of CQs per function (internal to FW) */ ;
	u8 reserved1;
	u8 protection_info;
#define FCOE_MSTORM_FCOE_CONN_ST_CTX_FP_SUPPORT_PROTECTION_MASK  0x1	/* Does this connection support protection (if couple of GOS share this connection it is enough that one of them support protection) */
#define FCOE_MSTORM_FCOE_CONN_ST_CTX_FP_SUPPORT_PROTECTION_SHIFT 0
#define FCOE_MSTORM_FCOE_CONN_ST_CTX_FP_VALID_MASK               0x1	/* Are we in protection perf mode (there is only one protection mode for this connection and we manage to create mss that contain fixed amount of protection segment and we are only restrict by the target limitation and not line mss this is critical since if line mss restrict us we cant rely on this size as it depends on vlan num) */
#define FCOE_MSTORM_FCOE_CONN_ST_CTX_FP_VALID_SHIFT              1
#define FCOE_MSTORM_FCOE_CONN_ST_CTX_FP_RESERVED0_MASK           0x3F
#define FCOE_MSTORM_FCOE_CONN_ST_CTX_FP_RESERVED0_SHIFT          2
	u8 q_relative_offset
	    /* CQ, RQ and CMDQ relative offset for connection */ ;
	u8 reserved2[2];
};

/*
 * Non fast path part of the fcoe storm context of Mstorm
 */
struct fcoe_mstorm_fcoe_conn_st_ctx_non_fp {
	__le16 conn_id
	    /* Driver connection ID. To be used by slowpaths to fill EQ placement params */
	    ;
	__le16 stat_ram_addr /* Statistics ram adderss */ ;
	__le16 num_pages_in_pbl
	    /* Number of XferQ/RespQ pbl pages (both have same wqe size) */ ;
	u8 ptu_log_page_size /* 0-4K, 1-8K, 2-16K, 3-32K... */ ;
	u8 log_page_size;
	__le16 unsolicited_cq_count
	    /* Counts number of CQs done due to unsolicited packets on this connection */
	    ;
	__le16 cmdq_count /* Counts number of CMDQs done on this connection */ ;
	u8 bdq_resource_id /* BDQ Resource ID */ ;
	u8 reserved0[3] /* Padding bytes for 2nd RegPair */ ;
	struct regpair xferq_pbl_addr /* XferQ Pbl base address */ ;
	struct regpair reserved1;
	struct regpair reserved2[3];
};

/*
 * The fcoe storm context of Mstorm
 */
struct mstorm_fcoe_conn_st_ctx {
	struct fcoe_mstorm_fcoe_conn_st_ctx_fp fp
	    /* Fast path part of the fcoe storm context of Mstorm */ ;
	struct fcoe_mstorm_fcoe_conn_st_ctx_non_fp non_fp
	    /* Non fast path part of the fcoe storm context of Mstorm */ ;
};

/*
 * fcoe connection context
 */
struct fcoe_conn_context {
	struct ystorm_fcoe_conn_st_ctx ystorm_st_context
	    /* ystorm storm context */ ;
	struct pstorm_fcoe_conn_st_ctx pstorm_st_context
	    /* pstorm storm context */ ;
	struct regpair pstorm_st_padding[2] /* padding */ ;
	struct xstorm_fcoe_conn_st_ctx xstorm_st_context
	    /* xstorm storm context */ ;
	struct xstorm_fcoe_conn_ag_ctx xstorm_ag_context
	    /* xstorm aggregative context */ ;
	struct regpair xstorm_ag_padding[6] /* padding */ ;
	struct ustorm_fcoe_conn_st_ctx ustorm_st_context
	    /* ustorm storm context */ ;
	struct regpair ustorm_st_padding[2] /* padding */ ;
	struct tstorm_fcoe_conn_ag_ctx tstorm_ag_context
	    /* tstorm aggregative context */ ;
	struct regpair tstorm_ag_padding[2] /* padding */ ;
	struct timers_context timer_context /* timer context */ ;
	struct ustorm_fcoe_conn_ag_ctx ustorm_ag_context
	    /* ustorm aggregative context */ ;
	struct tstorm_fcoe_conn_st_ctx tstorm_st_context
	    /* tstorm storm context */ ;
	struct mstorm_fcoe_conn_ag_ctx mstorm_ag_context
	    /* mstorm aggregative context */ ;
	struct mstorm_fcoe_conn_st_ctx mstorm_st_context
	    /* mstorm storm context */ ;
};

