#define DRV_MB_PARAM_NVM_CFG_OPTION_INIT_OFFSET         17
#define DRV_MB_PARAM_NVM_CFG_OPTION_INIT_MASK           0x00020000	/* When set, and state is IDLE, MFW will allocate resources and load configuration from NVM */
#define DRV_MB_PARAM_NVM_CFG_OPTION_COMMIT_OFFSET       18
#define DRV_MB_PARAM_NVM_CFG_OPTION_COMMIT_MASK         0x00040000	/* (Only for Set) - When set submit changed nvm_cfg1 to flash */
#define DRV_MB_PARAM_NVM_CFG_OPTION_FREE_OFFSET         19
#define DRV_MB_PARAM_NVM_CFG_OPTION_FREE_MASK           0x00080000	/* Free - When set, free allocated resources, and return to IDLE state. */
#define DRV_MB_PARAM_NVM_CFG_OPTION_ENTITY_SEL_OFFSET   20
#define DRV_MB_PARAM_NVM_CFG_OPTION_ENTITY_SEL_MASK     0x00100000	/* When set, command applies to the entity (func/port) in the ENTITY_ID field */
